#include <stdio.h>

/* teste do desafio o-movedor — counter_protocol (03-tdd 3.9.3).
   Fase VALOR: nao ha captura de stdout aqui. O teste declara o molde da
   ficha (o mesmo typedef do arquivo do aluno) e o prototipo da caixa, chama
   a caixa e confere os CAMPOS DEVOLVIDOS com checa_int. */

/* o tipo da ficha que a caixa do aluno recebe e devolve */
typedef struct {
    int x;
    int y;
} Ponto;

/* prototipo da funcao do aluno (o teste declara o que exercita) */
Ponto oMovedor(Ponto p, int dx, int dy);

SM_TEST(andar_1_e_2) {
    Ponto p;
    p.x = 3;
    p.y = 4;
    Ponto novo = oMovedor(p, 1, 2);
    checa_int("o x andou 1", novo.x, 4, "o x devolvido e o x da ficha mais dx");
    checa_int("o y andou 2", novo.y, 6, "o y devolvido e o y da ficha mais dy");
}

SM_TEST(a_ficha_de_fora_nao_muda) {
    Ponto p;
    p.x = 10;
    p.y = 20;
    oMovedor(p, 5, 7);
    checa_int("o x de fora ficou 10", p.x, 10, "a ficha entra como copia: o original nao anda");
    checa_int("o y de fora ficou 20", p.y, 20, "mexer no parametro nao mexe na ficha de quem chamou");
}

SM_TEST(andar_zero) {
    Ponto p;
    p.x = 7;
    p.y = 8;
    Ponto novo = oMovedor(p, 0, 0);
    checa_int("o x nao andou", novo.x, 7, "somar 0 devolve o mesmo x");
    checa_int("o y nao andou", novo.y, 8, "somar 0 devolve o mesmo y");
}

solutionCode:
#include <stdio.h>

typedef struct {
    int x;
    int y;
} Ponto;

Ponto oMovedor(Ponto p, int dx, int dy) {
    p.x = p.x + dx;
    p.y = p.y + dy;
    return p;
}
